import{_ as t,c as a,o as i,a2 as s}from"./chunks/framework.mqLGQ42V.js";const k=JSON.parse('{"title":"摇杆控制 (Joysticks) - Rive 编辑器","description":"摇杆控制 (Joysticks) 允许你通过一个简单的二维控制柄来驱动复杂的蒙皮和变形动画。 与其手动为成百上千个顶点设置复杂的关键帧，你可以将这些变形状态映射到一个摇杆上。通过移动摇杆，系统会自动在这些预设状态之间进行线性插值。","frontmatter":{"title":"摇杆控制 (Joysticks) - Rive 编辑器","description":"摇杆控制 (Joysticks) 允许你通过一个简单的二维控制柄来驱动复杂的蒙皮和变形动画。 与其手动为成百上千个顶点设置复杂的关键帧，你可以将这些变形状态映射到一个摇杆上。通过移动摇杆，系统会自动在这些预设状态之间进行线性插值。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 形状操控, 摇杆控制"}]]},"headers":[],"relativePath":"editor/manipulating-shapes/joysticks.md","filePath":"editor/manipulating-shapes/joysticks.md","lastUpdated":1774867914000}'),o={name:"editor/manipulating-shapes/joysticks.md"};function r(c,e,n,l,p,d){return i(),a("div",null,[...e[0]||(e[0]=[s('<p>操控形状</p><h1 id="摇杆控制-joysticks" tabindex="-1">摇杆控制 (Joysticks) <a class="header-anchor" href="#摇杆控制-joysticks" aria-label="Permalink to &quot;摇杆控制 (Joysticks)&quot;">​</a></h1><p>摇杆控制 (Joysticks) 允许你通过一个简单的二维控制柄来驱动复杂的蒙皮和变形动画。</p><h2 id="​-摇杆的核心威力" tabindex="-1"><a href="#the-power-of-joysticks">​</a> 摇杆的核心威力 <a class="header-anchor" href="#​-摇杆的核心威力" aria-label="Permalink to &quot;[​](#the-power-of-joysticks) 摇杆的核心威力&quot;">​</a></h2><p>与其手动为成百上千个顶点设置复杂的关键帧，你可以将这些变形状态映射到一个摇杆上。通过移动摇杆，系统会自动在这些预设状态之间进行线性插值。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 摇杆示例 Pn)</p></blockquote><h2 id="​-设置摇杆" tabindex="-1"><a href="#setting-up">​</a> 设置摇杆 <a class="header-anchor" href="#​-设置摇杆" aria-label="Permalink to &quot;[​](#setting-up) 设置摇杆&quot;">​</a></h2><ol><li>创建一个摇杆对象。</li><li>定义四个极值方向（上、下、左、右）的对象状态。</li><li>摇杆会根据控制柄的位置自动计算中间状态。</li></ol><p><a href="/docs/editor/manipulating-shapes/trim-path">路径裁剪 (Trim Path)</a><a href="/docs/editor/text/overview">文本概览 (Text Overview)</a></p>',9)])])}const m=t(o,[["render",r]]);export{k as __pageData,m as default};
